import { Component, OnInit, ViewChild } from '@angular/core';
import { GovBrTabModule, TabComponent, GovBrDatePickerModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ConsultarTransferenciasCbsComponent } from "./consultar-transferencias-cbs/consultar-transferencias-cbs.component";
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { Router } from '@angular/router';
import { MensagemService } from '../../services/mensagem.service';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs/internal/Subscription';
import { ConsultarRedutoresCompraGovernamentalComponent } from './consultar-redutores-compra-governamental/consultar-redutores-compra-governamental.component';

@Component({
  selector: 'consultar-compras-governamentais',
  templateUrl: './consultar-compras-governamentais.component.html',
  styleUrls: ['./consultar-compras-governamentais.component.scss'],
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrTabModule,
    GovBrDatePickerModule,
    ConsultarTransferenciasCbsComponent,
    ConsultarRedutoresCompraGovernamentalComponent,
    MyTitleComponent,
  ],
  providers: [],
})
export class ConsultarComprasGovernamentaisComponent implements OnInit {

  form!: FormGroup;
  dataConsulta: Date | null = null;

  @ViewChild(ConsultarTransferenciasCbsComponent)
  consultarTransferenciasCbsComponent!: ConsultarTransferenciasCbsComponent;

  @ViewChild(ConsultarRedutoresCompraGovernamentalComponent)
  consultarRedutoresCompraGovernamentalComponent!: ConsultarRedutoresCompraGovernamentalComponent;

  @ViewChild('brTabConsultarTransferenciasCbs') brTabConsultarTransferenciasCbs!: TabComponent;
  @ViewChild('brTabConsultarRedutoresCompraGovernamental') brTabConsultarRedutoresCompraGovernamental!: TabComponent;

  nomeTabConsultarTransferenciasCbs: string = 'Destinação da CBS';
  nomeTabConsultarRedutoresCompraGovernamental: string = 'Redutor de Alíquota';

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';

  constructor(
    private formBuilder: FormBuilder,
    private router: Router,
    private mensagemService: MensagemService,
    private dispositivoService: DispositivoService,
  ) { }

  ngOnInit(): void {
    this.form = this.formBuilder.group({
      dataControl: [new Date('01/01/2026'), [Validators.required]],
    });
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {
          this.nomeTabConsultarTransferenciasCbs = 'Destinação da CBS';
          this.nomeTabConsultarRedutoresCompraGovernamental = 'Redutor';
        } else {
          this.nomeTabConsultarTransferenciasCbs = 'Destinação da CBS';
          this.nomeTabConsultarRedutoresCompraGovernamental = 'Redutor de Alíquota';
        }
      }));
  }

  submit(event: any) {

  }

  onTabActiveChange(tab: TabComponent) {

  }

  voltar() {
    this.router.navigate(['/calculadora']);
  }

}
